// ─── HELPERS ───────────────────────────────────────────────────────────────────
const fmt = (p) => "$" + p.toLocaleString("es-CL");
const totalStock = (p) => Object.values(p.stock||{}).reduce((a,b)=>a+b,0);
function getColors(product) {
  const cfg = CATEGORY_CONFIG[product.category];
  const avColors = new Set(); const byColor = {};
  Object.entries(product.stock||{}).forEach(([key,qty]) => {
    if (qty>0) {
      const parts = key.split("-");
      if (cfg.hasColors && cfg.hasSizes) { const c=parts[0],s=parts[1]; avColors.add(c); if(!byColor[c]) byColor[c]=new Set(); byColor[c].add(s); }
      else if (cfg.hasColors) avColors.add(parts[0]);
    }
  });
  return { avColors:[...avColors], byColor };
}

// ─── PRODUCT CARD ─────────────────────────────────────────────────────────────
function ProductCard({ product, onConsult }) {
  const cfg = CATEGORY_CONFIG[product.category];
  const { avColors, byColor } = getColors(product);
  const [selColor, setSelColor] = useState(avColors[0]||null);
  const stock = totalStock(product);
  const sizes = selColor && byColor[selColor] ? [...byColor[selColor]] : [];
  const colorObjs = avColors.map(n=>COLORS.find(c=>c.name===n)).filter(Boolean);
  return (
    <div className="product-card">
      <div className="product-img-wrap">
        {product.image ? <img src={product.image} alt={product.name} className="product-img" /> : <span className="product-emoji">{product.emoji}</span>}
        <span className="cat-tag">{cfg.label}</span>
        {stock===0 && <span className="no-stock-badge">Sin stock</span>}
      </div>
      <div className="product-info">
        <h3 className="product-name">{product.name}</h3>
        <p className="product-desc">{product.description}</p>
        <div className="product-price">{fmt(product.price)}</div>
        {cfg.hasColors && colorObjs.length>0 && (
          <div className="color-section">
            <span className="sec-label">Colores:</span>
            <div className="color-dots">{colorObjs.map(c=>(
              <button key={c.name} className={`color-dot ${selColor===c.name?"selected":""} ${c.border?"bordered":""}`}
                style={{background:c.hex}} title={c.name} onClick={()=>setSelColor(c.name)} />
            ))}</div>
            {selColor && <span className="color-name-label">{selColor}</span>}
          </div>
        )}
        {cfg.hasSizes && sizes.length>0 && (
          <div className="size-section">
            <span className="sec-label">Tallas{selColor?` en ${selColor}`:""}:</span>
            <div className="size-tags">{(cfg.sizes||[]).filter(s=>sizes.includes(s)).map(s=><span key={s} className="size-tag">{s}</span>)}</div>
          </div>
        )}
        {stock>0 && <button className="consult-btn" onClick={()=>onConsult(product)}>Consultar / Pedir</button>}
      </div>
    </div>
  );
}

// ─── CONSULT MODAL ────────────────────────────────────────────────────────────
function ConsultModal({ product, onClose }) {
  const msg = encodeURIComponent(`Hola! Me interesa: *${product.name}* (${fmt(product.price)}). ¿Me das más información?`);
  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" onClick={e=>e.stopPropagation()}>
        <button className="modal-close" onClick={onClose}>✕</button>
        <div style={{fontSize:52,marginBottom:8}}>{product.image?<img src={product.image} alt="" style={{width:72,height:72,objectFit:"cover",borderRadius:12}} />:product.emoji}</div>
        <h3>{product.name}</h3>
        <p className="modal-price">{fmt(product.price)}</p>
        <p style={{color:"var(--text-mid)",fontSize:14,marginBottom:16}}>¿Cómo quieres contactarnos?</p>
        <a className="contact-btn whatsapp" href={`https://wa.me/${WHATSAPP_NUMBER}?text=${msg}`} target="_blank" rel="noreferrer">💬 WhatsApp</a>
        <a className="contact-btn instagram" href={`https://instagram.com/${INSTAGRAM_USER}`} target="_blank" rel="noreferrer">📸 Instagram</a>
      </div>
    </div>
  );
}

// ─── COTIZACIÓN ───────────────────────────────────────────────────────────────
function QuoteForm() {
  const [form, setForm] = useState({ name:"", phone:"", desc:"", size:"", qty:"", image:null });
  const [sent, setSent] = useState(false);
  const set = (k,v) => setForm(f=>({...f,[k]:v}));
  const handleImg = (e) => {
    const file = e.target.files[0]; if(!file) return;
    const reader = new FileReader();
    reader.onload = ev => set("image", ev.target.result);
    reader.readAsDataURL(file);
  };
  const handleSend = () => {
    if(!form.name||!form.phone||!form.desc||!form.size||!form.qty) return alert("Por favor completa todos los campos obligatorios.");
    const msg = encodeURIComponent(
      `🎨 *Cotización Sublimag*\n\n` +
      `👤 Nombre: ${form.name}\n` +
      `📱 Teléfono: ${form.phone}\n` +
      `📋 Descripción: ${form.desc}\n` +
      `📐 Tamaño del estampado: ${form.size}\n` +
      `🔢 Cantidad: ${form.qty}` +
      (form.image ? `\n\n📎 (Adjuntaré imagen por separado)` : "")
    );
    window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${msg}`, "_blank");
    setSent(true); setTimeout(()=>setSent(false), 4000);
  };
  return (
    <div className="quote-form">
      <h2 className="section-title">💬 Cotiza tu pedido</h2>
      <p className="section-sub">Completa el formulario y te responderemos a la brevedad por WhatsApp.</p>
      <div className="quote-grid">
        <div className="field-group">
          <label>Nombre *</label>
          <input placeholder="Tu nombre completo" value={form.name} onChange={e=>set("name",e.target.value)} />
        </div>
        <div className="field-group">
          <label>Número de celular *</label>
          <input placeholder="+56 9 XXXX XXXX" value={form.phone} onChange={e=>set("phone",e.target.value)} />
        </div>
      </div>
      <div className="field-group">
        <label>Descripción del trabajo * <span style={{color:"var(--text-light)",fontWeight:400}}>(incluye tipo de producto, diseño, colores, etc.)</span></label>
        <textarea rows={4} placeholder="Ej: Quiero sublimar una polera blanca talla M con un diseño de mi logo en el pecho..." value={form.desc} onChange={e=>set("desc",e.target.value)} />
      </div>
      <div className="quote-grid">
        <div className="field-group">
          <label>Tamaño del estampado * <span style={{color:"var(--text-light)",fontWeight:400}}>(ej: A4, 10x10cm...)</span></label>
          <input placeholder="Ej: A4, 20x30cm, pecho completo..." value={form.size} onChange={e=>set("size",e.target.value)} />
        </div>
        <div className="field-group">
          <label>Cantidad *</label>
          <input type="number" min="1" placeholder="Ej: 10" value={form.qty} onChange={e=>set("qty",e.target.value)} />
        </div>
      </div>
      <div className="field-group">
        <label>Imagen de referencia <span style={{color:"var(--text-light)",fontWeight:400}}>(opcional)</span></label>
        <div className="img-upload-box">
          <input type="file" accept="image/*" id="quote-img" onChange={handleImg} style={{display:"none"}} />
          <label htmlFor="quote-img" className="img-upload-label">
            {form.image
              ? <img src={form.image} alt="preview" style={{width:100,height:100,objectFit:"cover",borderRadius:10}} />
              : <><span style={{fontSize:32}}>🖼️</span><span>Toca para subir una imagen</span></>
            }
          </label>
        </div>
      </div>
      <button className="quote-btn" onClick={handleSend}>
        {sent ? "✓ ¡Enviado!" : "📤 Enviar cotización por WhatsApp"}
      </button>
    </div>
  );
}

