// ─── ADMIN LOGIN ──────────────────────────────────────────────────────────────
function AdminLogin({ onLogin, onBack }) {
  const [pw, setPw] = useState(""); const [err, setErr] = useState(false);
  const handle = () => { if(pw===ADMIN_PASSWORD) onLogin(); else { setErr(true); setTimeout(()=>setErr(false),1500); } };
  return (
    <div className="login-view">
      <button className="back-btn2" onClick={onBack}>← Volver al catálogo</button>
      <div className="login-box">
        <div style={{fontSize:40,marginBottom:12}}>🔐</div>
        <h2>Panel de Administración</h2>
        <p>Ingresa la contraseña para continuar</p>
        <input type="password" placeholder="Contraseña" value={pw}
          onChange={e=>setPw(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handle()}
          className={err?"shake":""} />
        {err && <p className="login-error">Contraseña incorrecta</p>}
        <button className="login-submit" onClick={handle}>Entrar</button>
        
      </div>
    </div>
  );
}

// ─── STOCK EDITOR ─────────────────────────────────────────────────────────────
function StockEditor({ product, onChange }) {
  const cfg = CATEGORY_CONFIG[product.category];
  const grouped = {};
  if (cfg.hasSizes && cfg.hasColors) COLORS.forEach(c=>{grouped[c.name]=(cfg.sizes||[]).map(s=>({key:`${c.name}-${s}`,label:s,hex:c.hex,border:c.border}));});
  else if (cfg.hasColors) COLORS.forEach(c=>{grouped[c.name]=[{key:`${c.name}-Único`,label:"Unidades",hex:c.hex,border:c.border}];});
  else grouped["Stock"]=[{key:"Único",label:"Unidades",hex:null}];
  return (
    <div className="stock-editor">
      {Object.entries(grouped).map(([g,items])=>(
        <div key={g} className="stock-group">
          <div className="stock-group-label">
            {items[0].hex && <span className="stock-color-dot" style={{background:items[0].hex,border:items[0].border?"1px solid #ccc":"none"}} />}
            {g}
          </div>
          <div className="stock-row">
            {items.map(({key,label})=>{
              const val=(product.stock||{})[key]??0;
              return (
                <div key={key} className="stock-cell">
                  <span className="stock-size-label">{label}</span>
                  <div className="stock-controls">
                    <button onClick={()=>onChange(key,Math.max(0,val-1))}>−</button>
                    <span className={`stock-num ${val===0?"zero":""}`}>{val}</span>
                    <button onClick={()=>onChange(key,val+1)}>+</button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
}

// ─── ADMIN PRODUCT ITEM ───────────────────────────────────────────────────────
function AdminProductItem({ product, onUpdate, onDelete }) {
  const [exp, setExp] = useState(false);
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState({...product});
  const save = () => { onUpdate(draft); setEditing(false); };
  const handleStockChange = (key,val) => { const ns={...(draft.stock||{}),[key]:val}; const u={...draft,stock:ns}; setDraft(u); onUpdate(u); };
  const handleImg = (e) => { const f=e.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=ev=>setDraft(d=>({...d,image:ev.target.result})); r.readAsDataURL(f); };
  const st = totalStock(product);
  return (
    <div className={`admin-product ${!product.active?"inactive":""}`}>
      <div className="admin-product-header" onClick={()=>setExp(e=>!e)}>
        <span style={{fontSize:24,flexShrink:0}}>
          {product.image?<img src={product.image} alt="" style={{width:32,height:32,objectFit:"cover",borderRadius:6}} />:product.emoji}
        </span>
        <div className="ap-info">
          <span className="ap-name">{product.name}</span>
          <span className="ap-meta">{CATEGORY_CONFIG[product.category]?.label} · {fmt(product.price)} · Stock: {st}</span>
        </div>
        <div className="ap-actions" onClick={e=>e.stopPropagation()}>
          <button className={`toggle-btn ${product.active?"on":"off"}`} onClick={()=>onUpdate({...product,active:!product.active})}>
            {product.active?"👁 Visible":"🚫 Oculto"}
          </button>
          <button className="edit-btn" onClick={()=>{setEditing(true);setExp(true);}}>✏️</button>
          <button className="delete-btn" onClick={()=>{if(window.confirm("¿Eliminar?"))onDelete(product.id);}}>🗑</button>
        </div>
        <span style={{color:"var(--text-light)",fontSize:11}}>{exp?"▲":"▼"}</span>
      </div>
      {exp && (
        <div className="admin-product-body">
          {editing ? (
            <div className="edit-form">
              <label>Nombre</label><input value={draft.name} onChange={e=>setDraft(d=>({...d,name:e.target.value}))} />
              <label>Precio (CLP)</label><input type="number" value={draft.price} onChange={e=>setDraft(d=>({...d,price:+e.target.value}))} />
              <label>Descripción</label><textarea value={draft.description} onChange={e=>setDraft(d=>({...d,description:e.target.value}))} />
              <label>Emoji</label><input value={draft.emoji} onChange={e=>setDraft(d=>({...d,emoji:e.target.value}))} />
              <label>Imagen del producto</label>
              <input type="file" accept="image/*" onChange={handleImg} style={{padding:"4px"}} />
              {draft.image && <img src={draft.image} alt="" style={{width:80,height:80,objectFit:"cover",borderRadius:8,marginTop:8}} />}
              <div className="edit-actions">
                <button className="save-btn" onClick={save}>✓ Guardar</button>
                <button className="cancel-btn" onClick={()=>{setEditing(false);setDraft({...product});}}>Cancelar</button>
              </div>
            </div>
          ) : <p style={{fontSize:13,color:"var(--text-mid)",padding:"12px 0 4px"}}>{product.description}</p>}
          <div className="stock-section"><h4>Gestión de Stock</h4><StockEditor product={draft} onChange={handleStockChange} /></div>
        </div>
      )}
    </div>
  );
}

// ─── ADD PRODUCT FORM ─────────────────────────────────────────────────────────
function AddProductForm({ onAdd, onCancel }) {
  const [form, setForm] = useState({name:"",category:"polera",price:"",description:"",emoji:"👕",active:true,image:null});
  const set = (k,v) => setForm(f=>({...f,[k]:v}));
  const handleImg = (e) => { const f=e.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=ev=>set("image",ev.target.result); r.readAsDataURL(f); };
  const submit = () => {
    if(!form.name||!form.price) return alert("Completa nombre y precio");
    const cfg=CATEGORY_CONFIG[form.category]; const stock={};
    if(cfg.hasSizes&&cfg.hasColors) COLORS.forEach(c=>(cfg.sizes||[]).forEach(s=>{stock[`${c.name}-${s}`]=0;}));
    else if(cfg.hasColors) COLORS.forEach(c=>{stock[`${c.name}-Único`]=0;});
    else stock["Único"]=0;
    onAdd({...form,price:+form.price,stock,id:Date.now()});
  };
  return (
    <div className="add-form">
      <h3>➕ Nuevo Producto</h3>
      <div className="form-grid">
        <div><label>Nombre *</label><input placeholder="Ej: Polera Vintage" value={form.name} onChange={e=>set("name",e.target.value)} /></div>
        <div><label>Categoría *</label><select value={form.category} onChange={e=>set("category",e.target.value)}>{Object.entries(CATEGORY_CONFIG).map(([k,v])=><option key={k} value={k}>{v.label}</option>)}</select></div>
        <div><label>Precio (CLP) *</label><input type="number" placeholder="12990" value={form.price} onChange={e=>set("price",e.target.value)} /></div>
        <div><label>Emoji</label><input placeholder="👕" value={form.emoji} onChange={e=>set("emoji",e.target.value)} /></div>
      </div>
      <label>Descripción</label><textarea placeholder="Describe el producto..." value={form.description} onChange={e=>set("description",e.target.value)} />
      <label>Imagen (opcional)</label><input type="file" accept="image/*" onChange={handleImg} style={{padding:"4px"}} />
      {form.image && <img src={form.image} alt="" style={{width:80,height:80,objectFit:"cover",borderRadius:8,marginTop:8}} />}
      <div className="add-actions">
        <button className="save-btn" onClick={submit}>✓ Agregar Producto</button>
        <button className="cancel-btn" onClick={onCancel}>Cancelar</button>
      </div>
    </div>
  );
}

// ─── ADMIN VIEW ───────────────────────────────────────────────────────────────
function AdminView({ products, setProducts, onBack }) {
  const [showAdd, setShowAdd] = useState(false);
  const update = (u) => setProducts(ps=>ps.map(p=>p.id===u.id?u:p));
  const remove = (id) => setProducts(ps=>ps.filter(p=>p.id!==id));
  const add = (p) => { setProducts(ps=>[...ps,p]); setShowAdd(false); };
  const st = products.reduce((a,p)=>a+totalStock(p),0);
  return (
    <div className="admin-view">
      <div className="admin-header">
        <button className="back-btn" onClick={onBack}>← Catálogo</button>
        <h2>⚙ Panel de Administración</h2>
      </div>
      <div className="stats-row">
        <div className="stat-card"><div className="stat-num">{products.length}</div><div className="stat-label">Productos</div></div>
        <div className="stat-card"><div className="stat-num">{products.filter(p=>p.active).length}</div><div className="stat-label">Visibles</div></div>
        <div className="stat-card"><div className="stat-num">{st}</div><div className="stat-label">En stock</div></div>
      </div>
      <div className="admin-toolbar">
        <h3>Productos ({products.length})</h3>
        <button className="add-product-btn" onClick={()=>setShowAdd(s=>!s)}>{showAdd?"✕ Cancelar":"➕ Nuevo Producto"}</button>
      </div>
      {showAdd && <AddProductForm onAdd={add} onCancel={()=>setShowAdd(false)} />}
      <div className="admin-products-list">{products.map(p=><AdminProductItem key={p.id} product={p} onUpdate={update} onDelete={remove} />)}</div>
    </div>
  );
}

// ─── ROOT APP ─────────────────────────────────────────────────────────────────
